create schema if not exists private;
create table if not exists public.beta_offer_stats (offer_key text primary key,total_slots integer not null check(total_slots>0),claimed_slots integer not null default 0 check(claimed_slots>=0 and claimed_slots<=total_slots),free_months integer not null default 12 check(free_months>0),updated_at timestamptz not null default now());
insert into public.beta_offer_stats(offer_key,total_slots,claimed_slots,free_months) values('founders-2026',10,0,12) on conflict(offer_key) do update set total_slots=excluded.total_slots,free_months=excluded.free_months,updated_at=now();
alter table public.beta_offer_stats enable row level security;
create policy beta_offer_stats_public_read on public.beta_offer_stats for select to anon,authenticated using(offer_key='founders-2026');
revoke all on public.beta_offer_stats from anon,authenticated; grant select on public.beta_offer_stats to anon,authenticated;
create table if not exists public.founder_entitlements(user_id uuid primary key references auth.users(id) on delete cascade,offer_key text not null references public.beta_offer_stats(offer_key),founder_number integer not null unique check(founder_number between 1 and 10),starts_at timestamptz not null,expires_at timestamptz not null,created_at timestamptz not null default now(),check(expires_at>starts_at));
create index if not exists idx_founder_entitlements_offer_key on public.founder_entitlements(offer_key);
alter table public.founder_entitlements enable row level security;
create policy founder_entitlements_select_own on public.founder_entitlements for select to authenticated using((select auth.uid())=user_id);
revoke all on public.founder_entitlements from anon,authenticated; grant select on public.founder_entitlements to authenticated;
create or replace function private.assign_founder_entitlement() returns trigger language plpgsql security definer set search_path='' as $$ declare assigned_number integer; start_time timestamptz; begin if new.email_confirmed_at is null or exists(select 1 from public.founder_entitlements where user_id=new.id) then return new; end if; update public.beta_offer_stats set claimed_slots=claimed_slots+1,updated_at=now() where offer_key='founders-2026' and claimed_slots<total_slots returning claimed_slots into assigned_number; if assigned_number is not null then start_time:=now(); insert into public.founder_entitlements(user_id,offer_key,founder_number,starts_at,expires_at) values(new.id,'founders-2026',assigned_number,start_time,start_time+interval '1 year') on conflict(user_id) do nothing; end if; return new; exception when others then raise warning 'Could not assign founder entitlement for user %',new.id; return new; end; $$;
revoke all on function private.assign_founder_entitlement() from public,anon,authenticated;
create trigger assign_founder_on_confirmation after insert or update of email_confirmed_at on auth.users for each row when(new.email_confirmed_at is not null) execute function private.assign_founder_entitlement();
create or replace function private.release_founder_entitlement() returns trigger language plpgsql security definer set search_path='' as $$ begin update public.beta_offer_stats set claimed_slots=greatest(claimed_slots-1,0),updated_at=now() where offer_key=old.offer_key; return old; end; $$;
revoke all on function private.release_founder_entitlement() from public,anon,authenticated;
create trigger release_founder_slot_on_delete after delete on public.founder_entitlements for each row execute function private.release_founder_entitlement();
